describe('ACVP SHA2-512-224 AFT (byte-aligned sub-sample)', () => {
    test.each(AFT)('tcId=$tc (len=$len bits): hash(msg) == md', (vec) => {
        const ba = hexToBitArray(vec.msg, vec.len);
        expect(_ba.bitLength(ba)).toBe(vec.len);
        const out = _h.hash(ba);
        expect(toHex(out)).toBe(vec.md.toLowerCase());
    });
});

